-- V45__packloading_flow_core.sql (renumbered from our V37 after the team's V44)
-- Deviation flow (unload/recheck/reload) + gate_pass closure columns + projection
-- + the Unload&Recheck page + non-conflicting step-page edits. Front-gate, QC and
-- the loading master are the team's now (V40/V43/V37) and are reconciled in V48.
SET @ts := NOW();

-- 1) (LoadingBay master removed — team V37 LoadingPoint is canonical; see V48)

-- 2) Route dropdown source
UPDATE entity_registry SET value_column='route_id', display_column='route_id' WHERE code='OrderDispatchDetail';

-- 3) gate_pass closure-check columns
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS seal_verified VARCHAR(24) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS weighment_verified VARCHAR(24) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS qc_clearance VARCHAR(24) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS order_recon_done VARCHAR(24) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS within_tolerance VARCHAR(24) NULL;

