INSERT IGNORE INTO page_version (page_id,version,status,body_json,created_at) SELECT id,1,'PUBLISHED','{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Unload \\u2192 Recheck \\u2192 Reload", "span": 12, "subtitle": "Manager sent this vehicle back: over-tolerance and camera did not explain it. Unload the FG stock, record the shortage/excess, then send for re-weigh + reload.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "expected_weight_kg": "expected_weight_kg", "loaded_weight_kg": "loaded_weight_kg", "pmt_variance_pct": "pmt_variance_pct"}, "scannable": true, "freeSolo": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "expected_weight_kg", "label": "Expected (kg)", "type": "text", "readOnly": true}, {"name": "loaded_weight_kg", "label": "Loaded so far (kg)", "type": "text", "readOnly": true}, {"name": "pmt_variance_pct", "label": "Variance %", "type": "text", "readOnly": true}, {"name": "discrepancy_type", "label": "Discrepancy", "type": "select", "required": true, "options": [{"label": "Shortage", "value": "SHORTAGE"}, {"label": "Excess", "value": "EXCESS"}]}, {"name": "discrepancy_qty", "label": "Shortage / Excess Qty", "type": "number", "required": true}, {"name": "variance_reason", "label": "Reason / Action Taken", "type": "textarea", "required": true}, {"name": "unload_supervisor", "label": "Unloading Supervisor", "type": "text", "required": true}]}, "children": [{"kind": "WorkflowActionButton", "label": "\\u2b07 Unloaded \\u2014 Send for Reload & Re-weigh", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "color": "primary"}]}]}]}]}',@ts FROM page_definition WHERE code='aria:pmt-unload-recheck';

-- 6) workflow_definition M10.PackLoading (deviation: reject -> unload -> reload)
UPDATE workflow_definition SET body_json='{"code": "M10.PackLoading", "version": 1, "initialState": "DRAFT", "states": [{"code": "DRAFT"}, {"code": "GATE_PASS_CREATED", "assignedRole": "ParkingSecurity"}, {"code": "PARKING_IN_1", "assignedRole": "Dispatch"}, {"code": "DISPATCH_VEHICLE_ENTRY", "assignedRole": "QC"}, {"code": "QC_PRELOAD_APPROVED", "assignedRole": "Planning"}, {"code": "QC_PRELOAD_REJECTED", "terminal": true}, {"code": "ORDER_SHEET_UPLOADED", "assignedRole": "Dispatch"}, {"code": "LOADING_ALLOCATED", "assignedRole": "WeighmentOfficer"}, {"code": "PARKING_OUT_1", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_1", "assignedRole": "LoadingSupervisor"}, {"code": "LOADING_IN_PROGRESS", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_2", "assignedRole": "LoadingSupervisor"}, {"code": "SEALING_DONE", "assignedRole": "ParkingSecurity"}, {"code": "PARKING_IN_2", "assignedRole": "PMTTeam"}, {"code": "PMT_CHECK_OK", "assignedRole": "BillingOfficer"}, {"code": "PMT_CAMERA_VERIFICATION", "assignedRole": "PMTTeam"}, {"code": "PMT_CHECK_PENDING_MANAGER", "assignedRole": "Manager"}, {"code": "RELOAD_REQUIRED", "assignedRole": "LoadingSupervisor"}, {"code": "BILLING_DONE", "assignedRole": "WeighmentOfficer"}, {"code": "PARKING_OUT_2", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_3", "assignedRole": "Manager"}, {"code": "READY_FOR_EXIT", "assignedRole": "FrontGate"}, {"code": "GATE_PASS_OUT_CLOSED", "terminal": true}, {"code": "REJECTED_BY_MANAGER", "terminal": true}, {"code": "UNLOAD_REQUIRED", "role": "UnloadingSupervisor"}], "transitions": [{"from": "DRAFT", "to": "GATE_PASS_CREATED", "trigger": "page.submitted", "pageCode": "aria:front-gate-create"}, {"from": "GATE_PASS_CREATED", "to": "PARKING_IN_1", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_IN_1", "to": "DISPATCH_VEHICLE_ENTRY", "trigger": "page.submitted", "pageCode": "aria:dispatch-vehicle-details"}, {"from": "DISPATCH_VEHICLE_ENTRY", "to": "QC_PRELOAD_APPROVED", "trigger": "page.submitted", "pageCode": "aria:qc-preload-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "DISPATCH_VEHICLE_ENTRY", "to": "QC_PRELOAD_REJECTED", "trigger": "page.submitted", "pageCode": "aria:qc-preload-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "QC_PRELOAD_APPROVED", "to": "ORDER_SHEET_UPLOADED", "trigger": "page.submitted", "pageCode": "aria:loading-order-sheet"}, {"from": "ORDER_SHEET_UPLOADED", "to": "LOADING_ALLOCATED", "trigger": "page.submitted", "pageCode": "aria:loading-allocation"}, {"from": "LOADING_ALLOCATED", "to": "PARKING_OUT_1", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_OUT_1", "to": "WEIGHMENT_1", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_1", "to": "LOADING_IN_PROGRESS", "trigger": "page.submitted", "pageCode": "aria:loading-in-progress"}, {"from": "LOADING_IN_PROGRESS", "to": "WEIGHMENT_2", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_2", "to": "SEALING_DONE", "trigger": "page.submitted", "pageCode": "aria:sealing-process"}, {"from": "SEALING_DONE", "to": "PARKING_IN_2", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_IN_2", "to": "PMT_CHECK_OK", "trigger": "page.submitted", "pageCode": "aria:pmt-weight-diff-check", "guard": "#submitted[''withinTolerance''] == ''YES''"}, {"from": "PARKING_IN_2", "to": "PMT_CAMERA_VERIFICATION", "trigger": "page.submitted", "pageCode": "aria:pmt-weight-diff-check", "guard": "#submitted[''withinTolerance''] == ''NO''"}, {"from": "PMT_CAMERA_VERIFICATION", "to": "PMT_CHECK_PENDING_MANAGER", "trigger": "page.submitted", "pageCode": "aria:pmt-camera-verification"}, {"from": "PMT_CHECK_PENDING_MANAGER", "to": "PMT_CHECK_OK", "trigger": "page.submitted", "pageCode": "aria:manager-qty-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "PMT_CHECK_PENDING_MANAGER", "to": "UNLOAD_REQUIRED", "trigger": "page.submitted", "pageCode": "aria:manager-qty-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "RELOAD_REQUIRED", "to": "WEIGHMENT_2", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "PMT_CHECK_OK", "to": "BILLING_DONE", "trigger": "page.submitted", "pageCode": "aria:billing-entry"}, {"from": "BILLING_DONE", "to": "PARKING_OUT_2", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_OUT_2", "to": "WEIGHMENT_3", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_3", "to": "READY_FOR_EXIT", "trigger": "page.submitted", "pageCode": "aria:manager-weight-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "WEIGHMENT_3", "to": "REJECTED_BY_MANAGER", "trigger": "page.submitted", "pageCode": "aria:manager-weight-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "READY_FOR_EXIT", "to": "GATE_PASS_OUT_CLOSED", "trigger": "page.submitted", "pageCode": "aria:gate-pass-closure-form", "guard": "(#submitted[''weighment_verified''] == ''OK'' || #submitted[''weighment_verified''] == ''MGR_APPROVED'') && (#submitted[''seal_verified''] == ''MATCHED'' || #submitted[''seal_verified''] == ''NA'') && #submitted[''invoice_count_verified''] == ''YES''"}, {"from": "UNLOAD_REQUIRED", "to": "RELOAD_REQUIRED", "pageCode": "aria:pmt-unload-recheck", "trigger": "page.submitted"}]}' WHERE code='M10.PackLoading';

