_weight_kg", "label": "Loaded (W1 \\u2212 W2) kg", "type": "text", "readOnly": true}, {"name": "pmt_variance_pct", "label": "Variance %", "type": "text", "readOnly": true}, {"name": "withinTolerance", "label": "System Verdict (auto \\u2014 \\u22640.4% = YES)", "type": "text", "readOnly": true}, {"name": "variance_reason", "label": "Variance Reason (required if over tolerance / to manager)", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Check OK", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CHECK_OK", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "Camera Verification", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CAMERA_VERIFICATION", "color": "warning"}]}]}]}]}' WHERE pd.code='aria:pmt-weight-diff-check' AND pv.status='PUBLISHED';
